package com.example.domain.amalan

object YasinData {
    val verses: List<YasinAyat> = listOf(
        YasinAyat(1, "يسٓ", "Yaa Siiiin.", "Ya Sin."),
        YasinAyat(2, "وَالْقُرْآنِ الْحَكِيمِ", "Wal qur-aanil hakiim.", "Demi Al-Qur'an yang penuh hikmah,"),
        YasinAyat(3, "إِنَّكَ لَمِنَ الْمُرْسَلِينَ", "Innaka laminal mursaliin.", "sungguh, engkau (Muhammad) benar-benar salah seorang dari para rasul,"),
        YasinAyat(4, "عَلَىٰ صِرَاطٍ مُسْتَقِيمٍ", "'Alaa shiraathim mustaqiim.", "(yang berada) di atas jalan yang lurus,"),
        YasinAyat(5, "تَنْزِيلَ الْعَزِيزِ الرَّحِيمِ", "Tanziilal 'aziizir rahiim.", "(sebagai wahyu) yang diturunkan oleh (Allah) Yang Maha Perkasa, Maha Penyayang,"),
        YasinAyat(6, "لِتُنْذِرَ قَوْمًا مَا أُنْذِرَ آبَاؤُهُمْ فَهُمْ غَافِلُونَ", "Litundzira qawmam maaa undzira aabaaa-uhum fahum ghaafiluun.", "agar engkau memberi peringatan kepada suatu kaum yang nenek moyangnya belum pernah diberi peringatan, karena itu mereka lalai."),
        YasinAyat(7, "لَقَدْ حَقَّ الْقَوْلُ عَلَىٰ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ", "Laqad haqqal qawlu 'alaaa aktsarihim fahum laa yu'minuun.", "Sungguh, pasti berlaku perkataan (hukuman) terhadap kebanyakan mereka, karena mereka tidak beriman."),
        YasinAyat(8, "إِنَّا جَعَلْنَا فِي أَعْنَاقِهِمْ أَغْلَالًا فَهِيَ إِلَى الْأَذْقَانِ فَهُمْ مُقْمَحُونَ", "Innaa ja'alnaa fiii a'naaqihim aghlaalan fahiya ilal adzqaani fahum muqmahuun.", "Sungguh, Kami telah memasang belenggu di leher mereka, lalu tangan mereka (diangkat) ke dagu, karena itu mereka tertengadah."),
        YasinAyat(9, "وَجَعَلْنَا مِنْ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَاهُمْ فَهُمْ لَا يُبْصِرُونَ", "Wa ja'alnaa mim bayni aydiihim saddaw wa min khalfihim saddan fa-aghsyaynaahum fahum laa yubshiruun.", "Dan Kami pasang sekat di hadapan mereka dan sekat di belakang mereka, dan Kami tutup mata mereka sehingga mereka tidak dapat melihat."),
        YasinAyat(10, "وَسَوَاءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لَا يُؤْمِنُونَ", "Wa sawaaa-un 'alayhim a-andzartahum am lam tundzirhum laa yu'minuun.", "Dan sama saja bagi mereka, apakah engkau memberi peringatan kepada mereka atau tidak memberi peringatan kepada mereka, mereka tidak akan beriman."),
        YasinAyat(11, "إِنَّمَا تُنْذِرُ مَنِ اتَّبَعَ الذِّكْرَ وَخَشِيَ الرَّحْمَٰنَ بِالْغَيْبِ ۖ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ", "Innamaa tundziru manittaba'adz dzikra wa khasyiyar rahmaana bil ghayb, fabasy-syirhu bi maghfiratiw wa ajrin kariim.", "Sesungguhnya engkau hanya memberi peringatan kepada orang-orang yang mau mengikuti peringatan dan yang takut kepada Tuhan Yang Maha Pengasih walaupun mereka tidak melihat-Nya. Maka berilah mereka kabar gembira dengan ampunan dan pahala yang mulia."),
        YasinAyat(12, "إِنَّا نَحْنُ نُحْيِي الْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ ۚ وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ فِي إِمَامٍ مُبِينٍ", "Innaa nahnu nuhyil mawtaa wa naktubu maa qaddamuu wa aatsaarahum, wa kulla syay-in ahshaynaahu fiii imaamim mubiin.", "Sungguh, Kamilah yang menghidupkan orang-orang yang mati, dan Kamilah yang mencatat apa yang telah mereka kerjakan dan bekas-bekas yang mereka tinggalkan. Dan segala sesuatu Kami kumpulkan dalam Kitab yang nyata (Lauh Mahfuzh)."),
        YasinAyat(13, "وَاضْرِبْ لَهُمْ مَثَلًا أَصْحَابَ الْقَرْيَةِ إِذْ جَاءَهَا الْمُرْسَلُونَ", "Wadhrib lahum matsalan ash-haabal qaryati idz jaaa-ahal mursaluun.", "Dan buatlah suatu perumpamaan bagi mereka, yaitu penduduk suatu negeri ketika para utusan datang kepada mereka;"),
        YasinAyat(14, "إِذْ أَرْسَلْنَا إِلَيْهِمُ اثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوا إِنَّا إِلَيْكُمْ مُرْسَلُونَ", "Idz arsalnaaa ilayhimuts-nayni fakadz-dzabuuhumaa fa-'azzaznaa bi tsaalitsin fa-qaaluuu innaaa ilaykum mursaluun.", "(yaitu) ketika Kami mengutus kepada mereka dua orang utusan, lalu mereka mendustakan keduanya; kemudian Kami kuatkan dengan (utusan) yang ketiga, maka ketiga utusan itu berkata: 'Sungguh, kami adalah orang-orang yang diutus kepadamu.'"),
        YasinAyat(15, "قَالُوا مَا أَنْتُمْ إِلَّا بَشَرٌ مِثْلُنَا وَمَا أَنْزَلَ الرَّحْمَٰنُ مِنْ شَيْءٍ إِنْ أَنْتُمْ إِلَّا تَكْذِبُونَ", "Qaaluu maaa antum illaa basyarum mitslunaa wa maaa anzalar rahmaanu min syay-in in antum illaa takdzibuun.", "Mereka (penduduk negeri) berkata: 'Kamu ini tidak lain hanyalah manusia seperti kami dan Allah Yang Maha Pengasih tidak menurunkan sesuatu apapun; kamu hanyalah berdusta belaka.'"),
        YasinAyat(16, "قَالُوا رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ", "Qaaluu rabbunaa ya'lamu innaaa ilaykum lamursaluun.", "Mereka berkata: 'Tuhan kami mengetahui sesungguhnya kami benar-benar diutus kepadamu,'"),
        YasinAyat(17, "وَمَا عَلَيْنَا إِلَّا الْبَلَاغُ الْمُبِينُ", "Wa maa 'alaynaaa illal balaaghul mubiin.", "'dan kewajiban kami tidak lain hanyalah menyampaikan (perintah Allah) dengan jelas.'"),
        YasinAyat(18, "قَالُوا إِنَّا تَطَيَّرْنَا بِكُمْ ۖ لَئِنْ لَمْ تَنْتَهُوا لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُمْ مِنَّا عَذَابٌ أَلِيمٌ", "Qaaluuu innaa tatay-yarnaa bikum, la-il lam tantahuu lanarjumannakum wa layamassannakum minnaa 'adzaabun aliim.", "Mereka menjawab: 'Sesungguhnya kami bernasib malang karena kamu; sungguh jika kamu tidak berhenti (menyeru kami), niscaya kami rajam kamu dan kamu pasti akan merasakan siksaan yang pedih dari kami.'"),
        YasinAyat(19, "قَالُوا طَائِرُكُمْ مَعَكُمْ ۚ أَئِنْ ذُكِّرْتُمْ ۚ بَلْ أَنْتُمْ قَوْمٌ مُسْرِفُونَ", "Qaaluu thaaa-irukum ma'akum, a-in dzukkirtum, bal antum qawmum musrifuun.", "Utusan-utusan itu berkata: 'Kemalangan kamu adalah karena kamu sendiri. Apakah jika kamu diberi peringatan (kamu mengancam kami)? Sebenarnya kamu adalah kaum yang melampaui batas.'"),
        YasinAyat(20, "وَجَاءَ مِنْ أَقْصَى الْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَا قَوْمِ اتَّبِعُوا الْمُرْسَلِينَ", "Wa jaaa-a min aqshal madiinati rajuluy yas'aa qaala yaa qawmittabi'ul mursaliin.", "Dan datanglah dari ujung kota seorang laki-laki (Habib An-Najjar) dengan bergegas-gegas dia berkata: 'Wahai kaumku! Ikutilah utusan-utusan itu.'"),
        YasinAyat(21, "اتَّبِعُوا مَنْ لَا يَسْأَلُكُمْ أَجْرًا وَهُمْ مُهْتَدُونَ", "Ittabi'uu mal laa yas-alukum ajraw wahum muhtaduun.", "Ikutilah orang yang tiada meminta balasan kepadamu; dan mereka adalah orang-orang yang mendapat petunjuk."),
        YasinAyat(22, "وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي وَإِلَيْهِ تُرْجَعُونَ", "Wa maa liya laaa a'budulladzii fatharanii wa ilayhi turja'uun.", "'Dan mengapa aku tidak menyembah (Tuhan) yang telah menciptakanku dan yang hanya kepada-Nya kamu akan dikembalikan?'"),
        YasinAyat(23, "أَأَتَّخِذُ مِنْ دُونِهِ آلِهَةً إِنْ يُرِدْنِ الرَّحْمَٰنُ بِضُرٍّ لَا تُغْنِ عَنِّي شَفَاعَتُهُمْ شَيْئًا وَلَا يُنْقِذُونِ", "A-attakhidzu min duunihiii aalihatan iy yuridnir rahmaanu bidhurril laa tughni 'annii syafaa'atuhum syay-aw wa laa yunqidzuun.", "'Mengapa aku akan menyembah tuhan-tuhan selain-Nya jika (Allah) Yang Maha Pengasih hendak mendatangkan bencana kepadaku, niscaya syafaat mereka tidak memberi manfaat sedikit pun bagiku dan mereka tidak dapat menyelamatkanku?'"),
        YasinAyat(24, "إِنِّي إِذًا لَفِي ضَلَالٍ مُبِينٍ", "Inniii idzal lafii dhalaalim mubiin.", "'Sesungguhnya jika aku (berbuat demikian), pasti aku berada dalam kesesatan yang nyata.'"),
        YasinAyat(25, "إِنِّي آمَنْتُ بِرَبِّكُمْ فَاسْمَعُونِ", "Inniii aamantu bi rabbikum fasma'uun.", "'Sesungguhnya aku telah beriman kepada Tuhanmu; maka dengarkanlah (pengakuan keimananku).'"),
        YasinAyat(26, "قِيلَ ادْخُلِ الْجَنَّةَ ۖ قَالَ يَا لَيْتَ قَوْمِي يَعْلَمُونَ", "Qiilad khulil jannah, qaala yaa layta qawmii ya'lamuun.", "Dikatakan (kepadanya): 'Masuklah ke surga.' Dia berkata: 'Alangkah baiknya sekiranya kaumku mengetahui,'"),
        YasinAyat(27, "بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ الْمُكْرَمِينَ", "Bimaa ghafara lii rabbii wa ja'alanii minal mukramiin.", "'apa yang menyebabkan Tuhanku memberi ampun kepadaku dan menjadikan aku termasuk orang-orang yang dimuliakan.'"),
        YasinAyat(28, "وَمَا أَنْزَلْنَا عَلَىٰ قَوْمِهِ مِنْ بَعْدِهِ مِنْ جُنْدٍ مِنَ السَّمَاءِ وَمَا كُنَّا مُنْزِلِينَ", "Wa maaa anzalnaa 'alaa qawmihii mim ba'dihii min jundim minas samaaa-i wa maa kunnaa munziliin.", "Dan setelah dia (meninggal), Kami tidak menurunkan suatu pasukan pun dari langit kepada kaumnya, dan Kami tidak perlu menurunkannya."),
        YasinAyat(29, "إِنْ كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ خَامِدُونَ", "In kaanat illaa shayhataw waahidatan fa-idzaa hum khaamiduun.", "Tidak ada siksaan atas mereka melainkan satu teriakan saja; maka seketika itu mereka mati (padam bagai api)."),
        YasinAyat(30, "يَا حَسْرَةً عَلَى الْعِبَادِ ۚ مَا يَأْتِيهِمْ مِنْ رَسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ", "Yaa hasratan 'alal 'ibaad, maa ya'tiihim mir rasuulin illaa kaanuu bihii yastahzi-uun.", "Alangkah besar penyesalan terhadap hamba-hamba itu, setiap kali seorang rasul datang kepada mereka, mereka selalu memperolok-olokkannya."),
        YasinAyat(31, "أَلَمْ يَرَوْا كَمْ أَهْلَكْنَا قَبْلَهُمْ مِنَ الْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ", "Alam yaraw kam ahlaknaa qablahum minal quruuni annahum ilayhim laa yarji'uun.", "Tidakkah mereka mengetahui berapa banyak umat sebelum mereka yang telah Kami binasakan, bahwa orang-orang (yang telah Kami binasakan) itu tidak ada yang kembali kepada mereka?"),
        YasinAyat(32, "وَإِنْ كُلٌّ لَمَّا جَمِيعٌ لَدَيْنَا مُحْضَرُونَ", "Wa in kullul lammaa jamii'ul ladaynaa muhdharuun.", "Dan setiap (umat), semuanya akan dihadapkan ke hadapan Kami."),
        YasinAyat(33, "وَآيَةٌ لَهُمُ الْأَرْضُ الْمَيْتَةُ أَحْيَيْنَاهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ", "Wa aayatul lahumul ardhul maytatu ahyaynaahaa wa akhrajnaa minhaa habban faminhu ya'kuluun.", "Dan suatu tanda (kebesaran Allah) bagi mereka adalah bumi yang mati (tandus); Kami hidupkan bumi itu dan Kami keluarkan darinya biji-bijian, maka dari biji-bijian itu mereka makan."),
        YasinAyat(34, "وَجَعَلْنَا فِيهَا جَنَّاتٍ مِنْ نَخِيلٍ وَأَعْنَابٍ وَفَجَّرْنَا فِيهَا مِنَ الْعُيُونِ", "Wa ja'alnaa fiihaa jannaatim min nakhiiliw wa a'naabiw wa fajjarnaa fiihaa minal 'uyuun.", "Dan Kami jadikan padanya kebun-kebun kurma dan anggur dan Kami pancarkan padanya beberapa mata air,"),
        YasinAyat(35, "لِيَأْكُلُوا مِنْ ثَمَرِهِ وَمَا عَمِلَتْهُ أَيْدِيهِمْ ۖ أَفَلَا يَشْكُرُونَ", "Liya'kuluu min tsamarihii wa maa 'amilat-hu aydiihim, afalaa yasykuruun.", "agar mereka dapat makan dari buahnya, dan dari apa yang diusahakan oleh tangan mereka. Maka mengapakah mereka tidak bersyukur?"),
        YasinAyat(36, "سُبْحَانَ الَّذِي خَلَقَ الْأَزْوَاجَ كُلَّهَا مِمَّا تُنْبِتُ الْأَرْضُ وَمِنْ أَنْفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ", "Subhaanalladzii khalaqal azwaaja kullahaa mimmaa tumbitul ardhu wa min anfusihim wa mimmaa laa ya'lamuun.", "Maha Suci (Allah) yang telah menciptakan semuanya berpasang-pasangan, baik dari apa yang ditumbuhkan oleh bumi dan dari diri mereka sendiri, maupun dari apa yang tidak mereka ketahui."),
        YasinAyat(37, "وَآيَةٌ لَهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ فَإِذَا هُمْ مُظْلِمُونَ", "Wa aayatul lahumul laylu naslakhu minhun nahaara fa-idzaa hum muzhlimuun.", "Dan suatu tanda (kebesaran Allah) bagi mereka adalah malam; Kami tanggalkan siang dari (malam) itu, maka seketika itu mereka (berada dalam) kegelapan,"),
        YasinAyat(38, "وَالشَّمْسُ تَجْرِي لِمُسْتَقَرٍّ لَهَا ۚ ذَٰلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ", "Wasy-syamsu tajrii limustaqarril lahaa, dzaalika taqdiirul 'aziizil 'aliim.", "dan matahari berjalan di tempat peredarannya. Demikianlah ketetapan (Allah) Yang Maha Perkasa, Maha Mengetahui."),
        YasinAyat(39, "وَالْقَمَرَ قَدَّرْنَاهُ مَنَازِلَ حَتَّىٰ عَادَ كَالْعُرْجُونِ الْقَدِيمِ", "Wal qamara qaddarnaahu manaazila hattaa 'aada kal 'urjuunil qadiim.", "Dan telah Kami tetapkan tempat peredaran bagi bulan, sehingga (setelah dia sampai ke fase terakhir) kembalilah dia seperti bentuk tandan yang tua."),
        YasinAyat(40, "لَا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ وَلَا اللَّيْلُ سَابِقُ النَّهَارِ ۚ وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ", "Lasy-syamsu yambaghii lahaaa an tudrikal qamara wa lal-laylu saabiqun nahaar, wa kullun fii falakiy yasbahuun.", "Tidaklah mungkin bagi matahari mengejar bulan dan malam pun tidak dapat mendahului siang. Masing-masing beredar pada garis edarnya."),
        YasinAyat(41, "وَآيَةٌ لَهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِي الْفُلْكِ الْمَشْحُونِ", "Wa aayatul lahum annaa hamalnaa dzurriyyatahum fil fulkil masyhuun.", "Dan suatu tanda (kebesaran Allah) bagi mereka adalah bahwa Kami angkut keturunan mereka dalam kapal yang penuh muatan,"),
        YasinAyat(42, "وَخَلَقْنَا لَهُمْ مِنْ مِثْلِهِ مَا يَرْكَبُونَ", "Wa khalaqnaa lahum mim mitslihii maa yarkabuun.", "dan Kami ciptakan (juga) untuk mereka dari jenis yang semisalnya apa yang mereka kendarai."),
        YasinAyat(43, "وَإِنْ نَشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنْقَذُونَ", "Wa in nasya' nughriq-hum falaa shariikha lahum wa laa hum yunqadzuun.", "Dan jika Kami menghendaki, Kami tenggelamkan mereka; maka tidak ada penolong bagi mereka dan tidak (pula) mereka diselamatkan,"),
        YasinAyat(44, "إِلَّا رَحْمَةً مِنَّا وَمَتَاعًا إِلَىٰ حِينٍ", "Illaa rahmatam minnaa wa mataa'an ilaa hiin.", "melainkan (Kami selamatkan mereka) karena rahmat yang besar dari Kami dan untuk memberi kesenangan hidup sampai suatu waktu."),
        YasinAyat(45, "وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ", "Wa idzaa qiila lahumuttaquu maa bayna aydiikum wa maa khalfakum la'allakum turhamuun.", "Dan apabila dikatakan kepada mereka: 'Takutlah kamu akan siksa yang di hadapanmu (di dunia) dan siksa yang akan datang (di akhirat) agar kamu mendapat rahmat,' (mereka berpaling)."),
        YasinAyat(46, "وَمَا تَأْتِيهِمْ مِنْ آيَةٍ مِنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ", "Wa maa ta'tiihim min aayatim min aayaati rabbihim illaa kaanuu 'anhaa mu'ridhiin.", "Dan setiap kali suatu tanda dari tanda-tanda (kebesaran) Tuhan datang kepada mereka, mereka selalu berpaling darinya."),
        YasinAyat(47, "وَإِذَا قِيلَ لَهُمْ أَنْفِقُوا مِمَّا رَزَقَكُمُ اللَّهُ قَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ آمَنُوا أَنُطْعِمُ مَنْ لَوْ يَشَاءُ اللَّهُ أَطْعَمَهُ إِنْ أَنْتُمْ إِلَّا فِي ضَلَالٍ مُبِينٍ", "Wa idzaa qiila lahum anfiquu mimmaa razaqakumullaahu qaalalladziina kafaruu lilladziina aamanuu anuth'imu mal law yasyaaa-ullaahu ath'amah, in antum illaa fii dhalaalim mubiin.", "Dan apabila dikatakan kepada mereka: 'Infakkanlah sebagian rezeki yang diberikan Allah kepadamu,' orang-orang yang kafir itu berkata kepada orang-orang yang beriman: 'Apakah kami harus memberi makan orang yang jika Allah menghendaki, Dia akan memberinya makan? Kamu benar-benar dalam kesesatan yang nyata.'"),
        YasinAyat(48, "وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِنْ كُنْتُمْ صَادِقِينَ", "Wa yaquuluuna mataa haadzal wa'du in kuntum shaadiqiin.", "Dan mereka berkata: 'Kapankah janji (hari berbangkit) ini (terjadi) jika kamu orang yang benar?'"),
        YasinAyat(49, "مَا يَنْظُرُونَ إِلَّا صَيْحَةً وَاحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ", "Maa yanzhuruuna illaa shayhataw waahidatan ta'khudzuhum wa hum yakhish-shimuun.", "Mereka hanya menunggu satu teriakan saja yang akan membinasakan mereka saat mereka sedang bertengkar."),
        YasinAyat(50, "فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَا إِلَىٰ أَهْلِهِمْ يَرْجِعُونَ", "Falaa yastathii'uuna tawshiyataw wa laaa ilaaa ahlihim yarji'uun.", "Maka mereka tidak mampu membuat suatu wasiat pun dan mereka (juga) tidak dapat kembali kepada keluarganya."),
        YasinAyat(51, "وَنُفِخَ فِي الصُّورِ فَإِذَا هُمْ مِنَ الْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنْسِلُونَ", "Wa nufikha fish-shuuri fa-idzaa hum minal ajdaatsi ilaa rabbihim yansiluun.", "Lalu ditiuplah sangkakala, maka seketika itu mereka keluar dari kuburnya (menuju) kepada Tuhan mereka dengan bergegas."),
        YasinAyat(52, "قَالُوا يَا وَيْلَنَا مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا ۜ ۗ هَٰذَا مَا وَعَدَ الرَّحْمَٰنُ وَصَدَقَ الْمُرْسَلُونَ", "Qaaluu yaa waylanaa mam ba'atsanaa mim marqadinaa, haadzaa maa wa'adar rahmaanu wa shadaqal mursaluun.", "Mereka berkata: 'Celakalah kami! Siapakah yang membangkitkan kami dari tempat tidur kami (kubur)?' (Lalu dikatakan kepada mereka): 'Inilah apa yang dijanjikan (Allah) Yang Maha Pengasih dan benarlah para rasul-Nya.'"),
        YasinAyat(53, "إِنْ كَانَتْ إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ جَمِيعٌ لَدَيْنَا مُحْضَرُونَ", "In kaanat illaa shayhataw waahidatan fa-idzaa hum jamii'ul ladaynaa muhdharuun.", "Teriakan itu hanya sekali saja, maka seketika itu mereka semua dihadapkan ke hadapan Kami."),
        YasinAyat(54, "فَالْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْئًا وَلَا تُجْزَوْنَ إِلَّا مَا كُنْتُمْ تَعْمَلُونَ", "Fal-yawma laa tuzhlamu nafsun syay-aw wa laa tujzawna illaa maa kuntum ta'maluun.", "Maka pada hari itu tidak ada seorang pun yang dizalimi sedikit pun dan kamu tidak diberi balasan melainkan sesuai dengan apa yang telah kamu kerjakan."),
        YasinAyat(55, "إِنَّ أَصْحَابَ الْجَنَّةِ الْيَوْمَ فِي شُغُلٍ فَاكِهُونَ", "Inna ash-haabal jannatil yawma fii syughulin faakihuun.", "Sesungguhnya penghuni surga pada hari itu bersenang-senang dalam kesibukan (penuh kenikmatan)."),
        YasinAyat(56, "هُمْ وَأَزْوَاجُهُمْ فِي ظِلَالٍ عَلَى الْأَرَائِكِ مُتَّكِئُونَ", "Hum wa azwaajuhum fii zhilaalin 'alal araaa-iki muttaki-uun.", "Mereka dan pasangan-pasangannya berada dalam tempat yang teduh, bersandar di atas dipan-dipan."),
        YasinAyat(57, "لَهُمْ فِيهَا فَاكِهَةٌ وَلَهُمْ مَا يَدَّعُونَ", "Lahum fiihaa faakihatuw wa lahum maa yadda'uun.", "Di surga itu mereka memperoleh buah-buahan dan memperoleh apa saja yang mereka inginkan."),
        YasinAyat(58, "سَلَامٌ قَوْلًا مِنْ رَبٍّ رَحِيمٍ", "Salaamun qawlam mir rabbir rahiim.", "(Kepada mereka dikatakan): 'Salam (keselamatan)', sebagai ucapan dari Tuhan Yang Maha Penyayang."),
        YasinAyat(59, "وَامْتَازُوا الْيَوْمَ أَيُّهَا الْمُجْرِمُونَ", "Wamtaazul yawma ayyuhal mujrimuun.", "'Dan (dikatakan kepada orang kafir): Berpisahlah kamu (dari orang mukmin) pada hari ini, wahai orang-orang yang berdosa!'"),
        YasinAyat(60, "أَلَمْ أَعْهَدْ إِلَيْكُمْ يَا بَنِي آدَمَ أَنْ لَا تَعْبُدُوا الشَّيْطَانَ ۖ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ", "Alam a'had ilaykum yaa baniii aadama al laa ta'budusy syaythaan, innahuu lakum 'aduwwum mubiin.", "Bukankah Aku telah memerintahkan kepadamu wahai anak cucu Adam agar kamu tidak menyembah setan? Sungguh, setan itu musuh yang nyata bagimu,"),
        YasinAyat(61, "وَأَنِ اعْبُدُونِي ۚ هَٰذَا صِرَاطٌ مُسْتَقِيمٌ", "Wa ani'buduunii, haadzaa shiraathum mustaqiim.", "dan hendaklah kamu menyembah-Ku. Inilah jalan yang lurus."),
        YasinAyat(62, "وَلَقَدْ أَضَلَّ مِنْكُمْ جِبِلًّا كَثِيرًا ۖ أَفَلَمْ تَكُونُوا تَعْقِلُونَ", "Wa laqad adhalla minkum jibillan katsiiraa, afalam takuunuu ta'qiluun.", "Dan sungguh, ia (setan) telah menyesatkan sebagian besar di antara kamu. Maka apakah kamu tidak mengerti?"),
        YasinAyat(63, "هَٰذِهِ جَهَنَّمُ الَّتِي كُنْتُمْ تُوعَدُونَ", "Haadzihii jahannamul latii kuntum tuu'aduun.", "Inilah (neraka) Jahanam yang dahulu telah diperingatkan kepadamu."),
        YasinAyat(64, "اصْلَوْهَا الْيَوْمَ بِمَا كُنْتُمْ تَكْفُرُونَ", "Ishlawhal yawma bimaa kuntum takfuruun.", "Masuklah ke dalamnya pada hari ini karena dahulu kamu mengingkarinya."),
        YasinAyat(65, "الْيَوْمَ نَخْتِمُ عَلَىٰ أَفْوَاهِهِمْ وَتُكَلِّمُنَا أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُمْ بِمَا كَانُوا يَكْسِبُونَ", "Al-yawma nakhtimu 'alaaa afwaahihim wa tukallimunaaa aydiihim wa tasy-hadu arjuluhum bimaa kaanuu yaksibuun.", "Pada hari ini Kami tutup mulut mereka; tangan mereka akan berkata kepada Kami dan kaki mereka akan memberi kesaksian terhadap apa yang dahulu mereka kerjakan."),
        YasinAyat(66, "وَلَوْ نَشَاءُ لَطَمَسْنَا عَلَىٰ أَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَاطَ فَأَنَّىٰ يُبْصِرُونَ", "Walaw nasyaaa-u lathamasnaa 'alaaa a'yunihim fastabaqush shiraatha fa-annaa yubshiruun.", "Dan jika Kami menghendaki, pastilah Kami hapuskan penglihatan mata mereka; lalu mereka berlomba-lomba mencari jalan. Maka bagaimana mereka dapat melihatnya?"),
        YasinAyat(67, "وَلَوْ نَشَاءُ لَمَسَخْنَاهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا اسْتَطَاعُوا مُضِيًّا وَلَا يَرْجِعُونَ", "Walaw nasyaaa-u lamasakhnaahum 'alaa makaanatihim famastathaa'uu mudhiyyaw wa laa yarji'uun.", "Dan jika Kami menghendaki, pastilah Kami ubah bentuk mereka di tempat mereka berada; sehingga mereka tidak sanggup berjalan maju dan tidak pula dapat kembali."),
        YasinAyat(68, "وَمَنْ نُعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ ۖ أَفَلَا يَعْقِلُونَ", "Wa man nu'ammirhu nunakkis-hu fil khalqi, afalaa ya'qiluun.", "Dan barangsiapa yang Kami panjangkan umurnya niscaya Kami kembalikan dia kepada kejadiannya (melemah seperti bayi). Maka apakah mereka tidak mengerti?"),
        YasinAyat(69, "وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنْبَغِي لَهُ ۚ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْآنٌ مُبِينٌ", "Wa maa 'allamnaahusy syi'ra wa maa yambaghii lah, in huwa illaa dzikruw wa qur-aanum mubiin.", "Dan Kami tidak mengajarkan syair kepadanya (Muhammad) dan bersyair itu tidak layak baginya. Al-Qur'an itu tidak lain hanyalah pelajaran dan Kitab yang jelas,"),
        YasinAyat(70, "لِيُنْذِرَ مَنْ كَانَ حَيًّا وَيَحِقَّ الْقَوْلُ عَلَى الْكَافِرِينَ", "Liyundzira man kaana hayyaw wa yahiqqal qawlu 'alal kaafiriin.", "agar dia memberi peringatan kepada orang-orang yang hidup (hatinya) dan agar pasti ketetapan azab terhadap orang-orang kafir."),
        YasinAyat(71, "أَوَلَمْ يَرَوْا أَنَّا خَلَقْنَا لَهُمْ مِمَّا عَمِلَتْ أَيْدِينَا أَنْعَامًا فَهُمْ لَهَا مَالِكُونَ", "Awa lam yaraw annaa khalaqnaa lahum mimmaa 'amilat aydiinaaa an'aaman fahum lahaa maalikuun.", "Dan tidakkah mereka melihat bahwa Kami telah menciptakan hewan ternak untuk mereka dari apa yang telah Kami ciptakan dengan kekuasaan Kami, lalu mereka menguasainya?"),
        YasinAyat(72, "وَذَلَّلْنَاهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ", "Wa dzallalnaahaa lahum faminhaa rakuubuhum wa minhaa ya'kuluun.", "Dan Kami tundukkan hewan-hewan itu untuk mereka; maka sebagiannya menjadi tunggangan mereka dan sebagiannya mereka makan."),
        YasinAyat(73, "وَلَهُمْ فِيهَا مَنَافِعُ وَمَشَارِبُ ۖ أَفَلَا يَشْكُرُونَ", "Wa lahum fiihaa manaafi'u wa masyaaribu, afalaa yasykuruun.", "Dan mereka memperoleh berbagai manfaat dan minuman darinya. Maka mengapakah mereka tidak bersyukur?"),
        YasinAyat(74, "وَاتَّخَذُوا مِنْ دُونِ اللَّهِ آلِهَةً لَعَلَّهُمْ يُنْصَرُونَ", "Wattakhadzuu min duunillaahi aalihatal la'allahum yunsharuun.", "Dan mereka mengambil sesembahan selain Allah agar mereka mendapat pertolongan."),
        YasinAyat(75, "لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُنْدٌ مُحْضَرُونَ", "Laa yastathii'uuna nashrahum wa hum lahum jundum muhdharuun.", "Sesembahan itu tidak mampu menolong mereka; padahal sesembahan itu menjadi tentara yang disiapkan untuk membela mereka."),
        YasinAyat(76, "فَلَا يَحْزُنْكَ قَوْلُهُمْ ۘ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ", "Falaa yahzunka qawluhum, innaa na'lamu maa yusirruuna wa maa yu'linuun.", "Maka jangan sampai perkataan mereka membuat engkau bersedih hati. Sungguh, Kami mengetahui apa yang mereka rahasiakan dan apa yang mereka nyatakan."),
        YasinAyat(77, "أَوَلَمْ يَرَ الْإِنْسَانُ أَنَّا خَلَقْنَاهُ مِنْ نُطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُبِينٌ", "Awa lam yaral insaanu annaa khalaqnaahu min nuthfatin fa-idzaa huwa khashiimum mubiin.", "Dan tidakkah manusia memperhatikan bahwa Kami menciptakannya dari setetes mani, ternyata dia menjadi musuh yang nyata!"),
        YasinAyat(78, "وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ ۖ قَالَ مَنْ يُحْيِي الْعِظَامَ وَهِيَ رَمِيمٌ", "Wa dharaba lanaa matsalaw wa nasiya khalqahu, qaala may yuhyil 'izhaama wa hiya ramiim.", "Dan dia membuat perumpamaan bagi Kami dan melupakan asal kejadiannya; dia berkata: 'Siapakah yang dapat menghidupkan tulang-belulang yang telah hancur luluh?'"),
        YasinAyat(79, "قُلْ يُحْيِيهَا الَّذِي أَنْشَأَهَا أَوَّلَ مَرَّةٍ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ", "Qul yuhyiihal ladziii ansya-ahaaa awwala marrah, wa huwa bikulli khalqin 'aliim.", "Katakanlah (Muhammad): 'Yang akan menghidupkannya ialah (Allah) yang menciptakannya pertama kali. Dan Dia Maha Mengetahui tentang segala makhluk,'"),
        YasinAyat(80, "الَّذِي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الْأَخْضَرِ نَارًا فَإِذَا أَنْتُمْ مِنْهُ تُوقِدُونَ", "Alladzii ja'ala lakum minasy syajaril akhdhari naaran fa-idzaaa antum minhu tuuqiduun.", "(yaitu) Tuhan yang menjadikan api untukmu dari kayu yang hijau, maka seketika itu kamu menyalakan (api) dari kayu itu."),
        YasinAyat(81, "أَوَلَيْسَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِقَادِرٍ عَلَىٰ أَنْ يَخْلُقَ مِثْلَهُمْ ۚ بَلَىٰ وَهُوَ الْخَلَّاقُ الْعَلِيمُ", "Awa laysalladzii khalaqas samaawaati wal ardha biqaadirin 'alaaa ay yakhluqa mitslahum, balaa wa huwal khallaaqul 'aliim.", "Dan bukankah (Allah) yang menciptakan langit dan bumi berkuasa menciptakan kembali yang serupa dengan mereka? Benar, dan Dia Maha Pencipta, Maha Mengetahui."),
        YasinAyat(82, "إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ", "Innamaaa amruhuuu idzaaa araada syay-an ay yaquula lahuu KUN FAYAKUUN.", "Sesungguhnya ketetapan-Nya apabila Dia menghendaki sesuatu hanyalah berkata kepadanya: 'JADILAH!' Maka terjadilah ia."),
        YasinAyat(83, "فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ", "Fa-subhaanalladzii biyadihii malakuutu kulli syay-iw wa ilayhi turja'uun.", "Maka Maha Suci (Allah) yang di tangan-Nya kekuasaan atas segala sesuatu dan kepada-Nya kamu dikembalikan.")
    )
}
